"""Application settings, loaded from ``CURA_*`` environment variables."""

from __future__ import annotations

from functools import lru_cache
from typing import Literal

from pydantic import Field
from pydantic_settings import BaseSettings, SettingsConfigDict

DISCLAIMER = (
    "Cura is a research prototype. Output is generated by deterministic rules "
    "and a small curated knowledge base, is not calibrated, and does not "
    "constitute medical advice, diagnosis, or treatment. Always involve a "
    "qualified clinician."
)


class Settings(BaseSettings):
    model_config = SettingsConfigDict(
        env_prefix="CURA_",
        env_file=".env",
        env_file_encoding="utf-8",
        extra="ignore",
    )

    app_name: str = "Cura"
    version: str = "0.1.0"
    environment: Literal["dev", "test", "prod"] = "dev"
    log_level: str = "INFO"
    disclaimer: str = DISCLAIMER
    cors_origins: list[str] = Field(default_factory=lambda: ["*"])

    # Case store
    store_backend: Literal["memory", "postgres"] = "postgres"
    store_max_cases: int = Field(default=1000, ge=1)
    database_url: str = "postgresql+psycopg://cura:cura@localhost:5433/cura"
    database_echo: bool = False

    # ML layer (lazy: models load on first use, never at import/lifespan)
    ml_enabled: bool = True
    ml_device: str = "cpu"
    ml_artifact_dir: str = "artifacts"
    embedding_model: str = "sentence-transformers/all-MiniLM-L6-v2"
    symptom_ml_threshold: float = Field(default=0.55, ge=0.0, le=1.0)
    symptom_ml_margin: float = Field(default=0.05, ge=0.0, le=1.0)
    lab_anomaly_contamination: float = Field(default=0.10, gt=0.0, lt=0.5)
    differential_ml_weight: float = Field(default=0.35, ge=0.0, le=1.0)
    drug_fuzzy_threshold: float = Field(default=0.84, ge=0.0, le=1.0)
    drug_embedding_threshold: float = Field(default=0.72, ge=0.0, le=1.0)

    # Symptom agent
    symptom_backend: Literal["auto", "lexicon", "scispacy"] = "auto"
    symptom_model: str = "en_core_sci_sm"

    # Differential diagnosis agent
    differential_top_k: int = Field(default=5, ge=1, le=20)
    differential_min_score: float = Field(default=0.05, ge=0.0, le=1.0)

    # Imaging agent: auto uses the X-ray model only when an image is supplied.
    imaging_backend: Literal["auto", "null", "hf"] = "auto"
    imaging_model_id: str = "nickmuchi/vit-finetuned-chest-xray-pneumonia"
    imaging_confidence_threshold: float = Field(default=0.55, ge=0.0, le=1.0)

    # Event bus (Kafka is optional; disabled by default)
    kafka_enabled: bool = False
    kafka_bootstrap_servers: str = "localhost:9092"
    kafka_topic_prefix: str = "cura"
    kafka_client_id: str = "cura-api"
    kafka_max_block_ms: int = Field(default=3000, ge=100)


@lru_cache
def get_settings() -> Settings:
    return Settings()
